// 1. 定义挡位枚举类型：有限状态机状态
typedef enum {
    GEAR_P = 0,   // 停车挡
    GEAR_R,       // 倒车挡
    GEAR_N,       // 空挡
    GEAR_D        // 前进挡
} GearState;
// 全局挡位变量，volatile防止编译器优化
volatile GearState gear = GEAR_P;
// 2. DWT消抖配置：50ms对应8400000个时钟周期
#define DEBOUNCE_CYCLES  8400000UL
static uint32_t last_interrupt_cycle = 0;  // 记录上一次中断计数值
/**
 * @brief  LED状态刷新函数：根据挡位更新两个LED电平
 * @param  state: 当前挡位状态
 * @retval 无
 */
static void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P:  // P挡：LED0亮，LED1灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_R:  // R挡：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N:  // N挡：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D:  // D挡：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        default: break;
    }
}
/**
 * @brief  挡位切换函数：实现P→R→N→D→P循环
 * @retval 无
 */
static void Gear_Shift(void)
{
    gear = (GearState)((uint8_t)gear + 1);
    if(gear > GEAR_D)  // 超出D挡则回到P挡
    {
        gear = GEAR_P;
    }
    LED_Update(gear);  // 切换后刷新LED
}
/**
 * @brief  GPIO外部中断统一回调函数
 * @param  GPIO_Pin: 触发中断的引脚
 * @retval 无
 */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == GPIO_PIN_4)  // 判断为PE4按键中断
    {
        uint32_t current_cycle = DWT_GetCycle();  // 读取当前DWT计数值
        // DWT消抖判断：间隔大于50ms才判定为有效按键
        if((current_cycle - last_interrupt_cycle) > DEBOUNCE_CYCLES)
        {
            last_interrupt_cycle = current_cycle;  // 更新中断时间戳
            Gear_Shift();  // 执行挡位切换
        }
    }
}
/**
 * @brief  主函数
 * @retval int
 */
int main(void)
{
    // HAL库初始化
    HAL_Init();
    // 配置系统时钟为168MHz
    SystemClock_Config();
    // 初始化GPIO与外部中断
    MX_GPIO_Init();
    MX_EXTI_Init();
    // 初始化DWT计数器，用于精准消抖
    DWT_Init();
    // 上电默认P挡，刷新LED
    LED_Update(gear);
    // 主循环：无业务逻辑，等待中断触发
    while (1)
    {
