/* 档位枚举定义 */
typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D
} GearState;

volatile GearState currentGear = GEAR_P;   // 当前档位
volatile uint32_t lastTick = 0;             // 上次按键的DWT计数

/* DWT初始化函数 */
static void DWT_Init(void) {
    if (!(CoreDebug->DEMCR & CoreDebug_DEMCR_TRCENA_Msk)) {
        CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;  // 使能跟踪
        DWT->CYCCNT = 0;                                 // 清空计数器
        DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;             // 使能CYCCNT
    }
}

/* 延时函数（微秒）*/
static void DWT_Delay_us(uint32_t us) {
    uint32_t start = DWT->CYCCNT;
    uint32_t cycles = us * (SystemCoreClock / 1000000);  // 转换为周期数
    while ((DWT->CYCCNT - start) < cycles);
}

/* LED更新函数 */
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);  // LED0亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);   // LED1灭
            break;
        case GEAR_R:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
    }
}

/* 档位切换函数 */
static void Gear_Shift(void) {
    switch(currentGear) {
        case GEAR_P: currentGear = GEAR_R; break;
        case GEAR_R: currentGear = GEAR_N; break;
        case GEAR_N: currentGear = GEAR_D; break;
        case GEAR_D: currentGear = GEAR_P; break;
    }
    LED_Update(currentGear);
}
4.3 中断服务程序说明
说明：请说明中断服务程序的配置方法、触发条件和处理逻辑
配置方法：在STM32CubeMX中，将PE4设置为“GPIO_EXTI4”，模式为“下降沿触发”，上拉。在NVIC设置中使能EXTI4中断，优先级设为0（最高）。
触发条件：当KEY0引脚从高电平跳变为低电平时（按键按下），硬件自动挂起EXTI4中断。
处理逻辑：
  1. 进入stm32f4xx_it.c中的EXTI4_IRQHandler()，该函数调用HAL_GPIO_EXTI_IRQHandler(KEY0_Pin)。
  2. 在HAL_GPIO_EXTI_Callback()中判断引脚，执行DWT消抖：读取当前DWT->CYCCNT，若与lastTick的差值大于等于50ms对应的周期数（168MHz * 0.05 = 8,400,000），则认为是有效按键。
  3. 有效按键后调用Gear_Shift()切换档位，并更新LED。4. 更新lastTick为当前计数值，清除中断标志。
