/* main.c - 汽车档位模拟器完整代码（基本要求部分）*/
#include "main.h"
#include "gpio.h"

/* 档位枚举 */
typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D
} GearState;

volatile GearState currentGear = GEAR_P;
volatile uint32_t lastTick = 0;

/* DWT初始化 */
static void DWT_Init(void) {
    if (!(CoreDebug->DEMCR & CoreDebug_DEMCR_TRCENA_Msk)) {
        CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
        DWT->CYCCNT = 0;
        DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
    }
}

/* 延时us（用于选做长按时）*/
static void DWT_Delay_us(uint32_t us) {
    uint32_t start = DWT->CYCCNT;
    uint32_t cycles = us * (SystemCoreClock / 1000000);
    while ((DWT->CYCCNT - start) < cycles);
}

/* LED更新 */
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
        case GEAR_R:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
        case GEAR_N:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
        case GEAR_D:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
    }
}

/* 档位切换 */
static void Gear_Shift(void) {
    switch(currentGear) {
        case GEAR_P: currentGear = GEAR_R; break;
        case GEAR_R: currentGear = GEAR_N; break;
        case GEAR_N: currentGear = GEAR_D; break;
        case GEAR_D: currentGear = GEAR_P; break;
    }
    LED_Update(currentGear);
}

/* 中断回调 */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if(GPIO_Pin == KEY0_Pin) {
        uint32_t now = DWT->CYCCNT;
        if(now - lastTick > 8400000) {  // 50ms @168MHz
            Gear_Shift();
            lastTick = now;
        }
    }
}

int main(void) {
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    DWT_Init();

    LED_Update(GEAR_P);   // 初始P档
    lastTick = DWT->CYCCNT;

    while(1) {
        // 可选：长按复位到P档（提高要求）
        if(HAL_GPIO_ReadPin(KEY0_GPIO_Port, KEY0_Pin) == GPIO_PIN_RESET) {
            uint32_t pressStart = DWT->CYCCNT;
            while(HAL_GPIO_ReadPin(KEY0_GPIO_Port, KEY0_Pin) == GPIO_PIN_RESET);
            uint32_t pressEnd = DWT->CYCCNT;
            if((pressEnd - pressStart) > (168000000 * 2)) { // 2秒
                currentGear = GEAR_P;
                LED_Update(currentGear);
            }
        }
    }
}
