/* 档位枚举类型 */
typedef enum
{
  GEAR_P = 0,   // 驻车档
  GEAR_R,       // 倒车档
  GEAR_N,       // 空档
  GEAR_D        // 前进档
} Gear_t;
/* 全局变量：当前档位，初始为 P 档 */
Gear_t current_gear = GEAR_P;
/**
  * @brief 根据当前档位更新 LED0、LED1 状态
  * @note  假设 LED 低电平有效（GPIO_PIN_RESET 点亮）
  */
void LED_Update(void)
{
  switch (current_gear)
  {
    case GEAR_P:  // P档：LED0灭 LED1灭
      HAL_GPIO_WritePin(GPIOF, LED0_Pin | LED1_Pin, GPIO_PIN_SET);
      break;
    case GEAR_R:  // R档：LED0亮 LED1灭
      HAL_GPIO_WritePin(GPIOF, LED0_Pin, GPIO_PIN_RESET);
      HAL_GPIO_WritePin(GPIOF, LED1_Pin, GPIO_PIN_SET);
      break;
    case GEAR_N:  // N档：LED0灭 LED1亮
      HAL_GPIO_WritePin(GPIOF, LED0_Pin, GPIO_PIN_SET);
      HAL_GPIO_WritePin(GPIOF, LED1_Pin, GPIO_PIN_RESET);
      break;
    case GEAR_D:  // D档：LED0亮 LED1亮
      HAL_GPIO_WritePin(GPIOF, LED0_Pin | LED1_Pin, GPIO_PIN_RESET);
      break;
    default:
      break;
  }
}
/**
  * @brief 档位切换函数：循环切换 P -> R -> N -> D -> P ...
  *        切换后自动更新 LED 显示
  */
void Gear_Shift(void)
{
  switch (current_gear)
  {
    case GEAR_P:
      current_gear = GEAR_R;
      break;
    case GEAR_R:
      current_gear = GEAR_N;
      break;
    case GEAR_N:
      current_gear = GEAR_D;
      break;
    case GEAR_D:
      current_gear = GEAR_P;
      break;
    default:
      current_gear = GEAR_P;
      break;
  }
  LED_Update();   // 更新 LED 显示
}
/**
  * @brief 外部中断回调函数，由 HAL 库在 EXTI4_IRQHandler 中调用
  * @param GPIO_Pin 触发中断的引脚
  */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
  if (GPIO_Pin == KEY0_Pin)   // KEY0 对应 PE4 引脚
  {
    Gear_Shift();             // 切换档位
  }
}
